pub struct OILConflictBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> OILConflictBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_LEFT_IDS(&mut self, LEFT_IDS: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , ::flatbuffers::ForwardsUOffset<&'b  str>>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(OILConflict::VT_LEFT_IDS, LEFT_IDS);
    }

    #[inline]
    pub fn add_RIGHT_IDS(&mut self, RIGHT_IDS: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , ::flatbuffers::ForwardsUOffset<&'b  str>>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(OILConflict::VT_RIGHT_IDS, RIGHT_IDS);
    }

    #[inline]
    pub fn add_SHAPE(&mut self, SHAPE: oilConflictShape) {
        self.fbb_.push_slot::<oilConflictShape>(OILConflict::VT_SHAPE, SHAPE, oilConflictShape::Unspecified);
    }

    #[inline]
    pub fn add_REASON(&mut self, REASON: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(OILConflict::VT_REASON, REASON);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> OILConflictBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        OILConflictBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<OILConflict<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

