#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct OILConflictT {
    pub LEFT_IDS: Option<alloc::vec::Vec<alloc::string::String>>,
    pub RIGHT_IDS: Option<alloc::vec::Vec<alloc::string::String>>,
    pub SHAPE: oilConflictShape,
    pub REASON: Option<alloc::string::String>,
}

impl Default for OILConflictT {
    fn default() -> Self {
        Self {
            LEFT_IDS: None,
            RIGHT_IDS: None,
            SHAPE: oilConflictShape::Unspecified,
            REASON: None,
        }
    }
}

impl OILConflictT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<OILConflict<'b>> {
        let LEFT_IDS = self.LEFT_IDS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|s| _fbb.create_string(s)).collect();_fbb.create_vector(&w)
        });
        let RIGHT_IDS = self.RIGHT_IDS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|s| _fbb.create_string(s)).collect();_fbb.create_vector(&w)
        });
        let SHAPE = self.SHAPE;
        let REASON = self.REASON.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        OILConflict::create(_fbb, &OILConflictArgs{
            LEFT_IDS,
            RIGHT_IDS,
            SHAPE,
            REASON,
        })
    }
}

