#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct OILT {
    pub PROVIDER: Option<alloc::string::String>,
    pub KIND: Option<alloc::string::String>,
    pub LEFT_NAMESPACE: Option<alloc::string::String>,
    pub RIGHT_NAMESPACE: Option<alloc::string::String>,
    pub HEADER: Option<alloc::string::String>,
    pub SHA256: Option<alloc::string::String>,
    pub BYTES: u64,
    pub ROWS: u32,
    pub DUPLICATE_LINES: u32,
    pub LINK_COUNT: u32,
    pub CLEAN_COUNT: u32,
    pub AMBIGUOUS_COUNT: u32,
    pub LEFT_ID_COUNT: u32,
    pub RIGHT_ID_COUNT: u32,
    pub DATES_DIFFER_COUNT: u32,
    pub UNREADABLE_DATE_COUNT: u32,
    pub LINKS: Option<alloc::vec::Vec<OILLinkT>>,
    pub CONFLICTS: Option<alloc::vec::Vec<OILConflictT>>,
    pub GENERATED_AT_MS: i64,
}

impl Default for OILT {
    fn default() -> Self {
        Self {
            PROVIDER: None,
            KIND: None,
            LEFT_NAMESPACE: None,
            RIGHT_NAMESPACE: None,
            HEADER: None,
            SHA256: None,
            BYTES: 0,
            ROWS: 0,
            DUPLICATE_LINES: 0,
            LINK_COUNT: 0,
            CLEAN_COUNT: 0,
            AMBIGUOUS_COUNT: 0,
            LEFT_ID_COUNT: 0,
            RIGHT_ID_COUNT: 0,
            DATES_DIFFER_COUNT: 0,
            UNREADABLE_DATE_COUNT: 0,
            LINKS: None,
            CONFLICTS: None,
            GENERATED_AT_MS: 0,
        }
    }
}

impl OILT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<OIL<'b>> {
        let PROVIDER = self.PROVIDER.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let KIND = self.KIND.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let LEFT_NAMESPACE = self.LEFT_NAMESPACE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let RIGHT_NAMESPACE = self.RIGHT_NAMESPACE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let HEADER = self.HEADER.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let SHA256 = self.SHA256.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let BYTES = self.BYTES;
        let ROWS = self.ROWS;
        let DUPLICATE_LINES = self.DUPLICATE_LINES;
        let LINK_COUNT = self.LINK_COUNT;
        let CLEAN_COUNT = self.CLEAN_COUNT;
        let AMBIGUOUS_COUNT = self.AMBIGUOUS_COUNT;
        let LEFT_ID_COUNT = self.LEFT_ID_COUNT;
        let RIGHT_ID_COUNT = self.RIGHT_ID_COUNT;
        let DATES_DIFFER_COUNT = self.DATES_DIFFER_COUNT;
        let UNREADABLE_DATE_COUNT = self.UNREADABLE_DATE_COUNT;
        let LINKS = self.LINKS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let CONFLICTS = self.CONFLICTS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let GENERATED_AT_MS = self.GENERATED_AT_MS;
        OIL::create(_fbb, &OILArgs{
            PROVIDER,
            KIND,
            LEFT_NAMESPACE,
            RIGHT_NAMESPACE,
            HEADER,
            SHA256,
            BYTES,
            ROWS,
            DUPLICATE_LINES,
            LINK_COUNT,
            CLEAN_COUNT,
            AMBIGUOUS_COUNT,
            LEFT_ID_COUNT,
            RIGHT_ID_COUNT,
            DATES_DIFFER_COUNT,
            UNREADABLE_DATE_COUNT,
            LINKS,
            CONFLICTS,
            GENERATED_AT_MS,
        })
    }
}

/// Verifies that a buffer of bytes contains a `OIL`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_oil_unchecked`.
#[inline]
pub fn root_as_oil(buf: &[u8]) -> Result<OIL<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<OIL>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `OIL` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_oil_unchecked`.
#[inline]
pub fn size_prefixed_root_as_oil(buf: &[u8]) -> Result<OIL<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<OIL>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `OIL` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_oil_unchecked`.
#[inline]
pub fn root_as_oil_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<OIL<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<OIL<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `OIL` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_oil_unchecked`.
#[inline]
pub fn size_prefixed_root_as_oil_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<OIL<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<OIL<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a OIL and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `OIL`.
#[inline]
pub unsafe fn root_as_oil_unchecked(buf: &[u8]) -> OIL<'_> {
    unsafe { ::flatbuffers::root_unchecked::<OIL>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed OIL and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `OIL`.
#[inline]
pub unsafe fn size_prefixed_root_as_oil_unchecked(buf: &[u8]) -> OIL<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<OIL>(buf) }
}

pub const OIL_IDENTIFIER: &str = "$OIL";

#[inline]
pub fn oil_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, OIL_IDENTIFIER, false)
}

#[inline]
pub fn oil_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, OIL_IDENTIFIER, true)
}

#[inline]
pub fn finish_oil_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<OIL<'a>>
) {
    fbb.finish(root, Some(OIL_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_oil_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<OIL<'a>>
) {
    fbb.finish_size_prefixed(root, Some(OIL_IDENTIFIER));
}
